// ---------------------------------------------------------------------------
// user.factory.ts — Synthetic data factory for auth.users inserts.
//
// Produces deterministic fake data suitable for unit / integration tests.
// Does NOT include id, created_at, or updated_at — those are generated by the
// database on insert.
// ---------------------------------------------------------------------------

export interface NewUser {
  email: string;
  passwordHash: string;
}

/** Internal counter — increments on each {@link buildUser} call. */
let counter = 0;

/**
 * Resets the internal counter to 0.
 * Call this in a `beforeEach` / `afterEach` hook to keep tests deterministic.
 */
export function resetUserCounter(): void {
  counter = 0;
}

/**
 * Builds a plain object matching the shape required for an `auth.users` insert.
 *
 * - `email` is always lowercase (satisfying the normalisation requirement).
 * - `passwordHash` is a stable bcrypt-like placeholder (not a real hash).
 *
 * @param overrides - Any fields to override on the generated object.
 * @returns A `NewUser` object ready to pass to `db.insert(users).values(…)`.
 *
 * @example
 * ```ts
 * const user = buildUser({ email: 'custom@example.com' });
 * await db.insert(users).values(user);
 * ```
 */
export function buildUser(overrides: Partial<NewUser> = {}): NewUser {
  const index = ++counter;

  return {
    email: `test.user.${index}@devpath.test`,
    // Deterministic placeholder — safe to use in DB inserts during tests.
    passwordHash: `$2b$10$fakehashforfactory.user${String(index).padStart(4, '0')}`,
    ...overrides,
  };
}
